const message = $input.first().json.message;
const userId = message.from.id;
const userName = message.from.first_name;
const text = message.text || '';
const chatId = message.chat.id;

if (text.startsWith('/start')) {
  return { json: { command: 'start', user_id: userId, user_name: userName, chat_id: chatId } };
}

if (text.startsWith('/help')) {
  return { json: { command: 'help', user_id: userId, user_name: userName, chat_id: chatId } };
}

const category = text.replace('/search', '').trim();
return {
  json: {
    command: 'search',
    user_id: userId,
    user_name: userName,
    chat_id: chatId,
    category: category || 'wireless headphones'
  }
};

const input = $input.first().json;
const category = input.category;
const chatId = input.chat_id;
const userId = input.user_id;
const userName = input.user_name;

const suppliers = [
  { company_name: 'Yiwu Wholesale Trading Co.', rating: 4.9, moq: '200 шт', price: '$3.80', location: 'Zhejiang', contact_email: 'export@yiwu-wholesale.com', company_url: 'https://yiwu-wholesale.en.alibaba.com' },
  { company_name: 'Shanghai Premium Exports', rating: 4.7, moq: '300 шт', price: '$6.50', location: 'Shanghai', contact_email: 'export@sh-premium.com', company_url: 'https://sh-premium.en.alibaba.com' },
  { company_name: 'Shenzhen Tech Electronics', rating: 4.8, moq: '100 шт', price: '$5.50', location: 'Guangdong', contact_email: 'sales@shenzhen-tech.com', company_url: 'https://shenzhen-tech.en.alibaba.com' }
];

const result = suppliers.map(s => ({
  json: {
    company_name: s.company_name,
    rating: s.rating,
    moq: s.moq,
    price: s.price,
    location: s.location,
    contact_email: s.contact_email,
    company_url: s.company_url,
    category: category,
    chat_id: chatId,
    user_id: userId
  }
}));

return result;

const items = $input.all();

if (!items || items.length === 0) {
  throw new Error('Нет данных от Generate Suppliers!');
}

const chatId = items[0].json.chat_id;
const category = items[0].json.category;

if (!chatId) {
  throw new Error('chat_id отсутствует в данных!');
}

let message = `📊 *${category}* (${items.length} компаний)\n\n`;

items.forEach((item, i) => {
  const d = item.json;
  message += `⭐️ *${i+1}. ${d.company_name}*\n`;
  message += `📊 ${d.rating}/5 | 📦 ${d.moq} | 💰 ${d.price}\n`;
  message += `📍 ${d.location}\n`;
  message += `📧 ${d.contact_email}\n`;
  message += `🌐 ${d.company_url}\n\n`;
});

return [{
  json: {
    chat_id: chatId,
    message: message
  }
}];
